"""File-based storage for sessions. Everything lives under data/ so it's easy to back up."""

import json
import shutil
import threading
import time
import uuid
from pathlib import Path

DATA_DIR = Path(__file__).parent / "data"
SESSIONS_DIR = DATA_DIR / "sessions"
SETTINGS_FILE = DATA_DIR / "settings.json"

_lock = threading.RLock()


def _write_json(path: Path, data) -> None:
    tmp = path.with_suffix(".tmp")
    tmp.write_text(json.dumps(data, indent=2))
    tmp.replace(path)


def session_dir(session_id: str) -> Path:
    # Session ids are generated by us; reject anything else to avoid path tricks.
    if not session_id.isalnum():
        raise KeyError(session_id)
    return SESSIONS_DIR / session_id


def chunks_dir(session_id: str) -> Path:
    return session_dir(session_id) / "chunks"


def transcripts_dir(session_id: str) -> Path:
    return session_dir(session_id) / "transcripts"


def create_session(title: str, source: str) -> dict:
    session_id = uuid.uuid4().hex[:12]
    d = session_dir(session_id)
    chunks_dir(session_id).mkdir(parents=True)
    transcripts_dir(session_id).mkdir(parents=True)
    session = {
        "id": session_id,
        "title": title,
        "source": source,  # "mic" or "upload"
        "created_at": time.time(),
        "status": "recording" if source == "mic" else "preparing",
        "recording_finished": False,
        "chunk_count": 0,
        "error": None,
    }
    _write_json(d / "session.json", session)
    return session


def get_session(session_id: str) -> dict:
    path = session_dir(session_id) / "session.json"
    if not path.exists():
        raise KeyError(session_id)
    with _lock:
        return json.loads(path.read_text())


def update_session(session_id: str, **changes) -> dict:
    with _lock:
        session = get_session(session_id)
        session.update(changes)
        _write_json(session_dir(session_id) / "session.json", session)
        return session


def list_sessions() -> list[dict]:
    if not SESSIONS_DIR.exists():
        return []
    sessions = []
    for d in SESSIONS_DIR.iterdir():
        try:
            sessions.append(get_session(d.name))
        except (KeyError, json.JSONDecodeError):
            continue
    return sorted(sessions, key=lambda s: s["created_at"], reverse=True)


def delete_session(session_id: str) -> None:
    shutil.rmtree(session_dir(session_id), ignore_errors=True)


def chunk_indexes(session_id: str) -> list[int]:
    return sorted(int(p.stem) for p in chunks_dir(session_id).iterdir() if p.stem.isdigit())


def transcribed_indexes(session_id: str) -> set[int]:
    return {int(p.stem) for p in transcripts_dir(session_id).glob("*.json")}


def save_chunk_transcript(session_id: str, index: int, data: dict) -> None:
    _write_json(transcripts_dir(session_id) / f"{index:04d}.json", data)


def build_transcript(session_id: str) -> str:
    """Stitch chunk transcripts into one timestamped transcript."""
    lines = []
    offset = 0.0
    for path in sorted(transcripts_dir(session_id).glob("*.json")):
        chunk = json.loads(path.read_text())
        for seg in chunk["segments"]:
            t = int(offset + seg["start"])
            lines.append(f"[{t // 3600:d}:{t % 3600 // 60:02d}:{t % 60:02d}] {seg['text']}")
        offset += chunk["duration"]
    return "\n".join(lines)


def notes_path(session_id: str) -> Path:
    return session_dir(session_id) / "notes.md"


def get_settings() -> dict:
    if SETTINGS_FILE.exists():
        return json.loads(SETTINGS_FILE.read_text())
    return {"campaign_context": ""}


def save_settings(settings: dict) -> dict:
    DATA_DIR.mkdir(exist_ok=True)
    _write_json(SETTINGS_FILE, settings)
    return settings
